      "source_id": "q2",
      "actor": "system",
      "role": "policy",
      "fact": "Assistant must not make up or assume information not provided by user or tools."
    },
    {
      "source_id": "h5",
      "actor": "user",
      "role": "requester",
      "fact": "User provided `45.0` (base amount) and `12.5` (late fee) as explicit values."
